async function playTournament(clients,api,click,url){
 const count=clients.length,indices=Array.from({length:count},(_,i)=>i);
 const state=async(i=0)=>(await api(clients[i]))[1];
 let s=await state(),last=0,stackBefore=Array(count).fill(100),sawHeadsUp=false,sawIncrease=false;
 assert.equal(s.tournament.pool,count*25);assert.deepEqual(s.names,indices.map(i=>'Player'+(i+1)));assert.equal(s.hand.blind,4);
 // Let a scheduled boundary pass without changing the blinds or bets mid-hand.
 await delay(10100);s=await state();assert.equal(s.hand.blind,4);
 const eliminated=new Set();
 for(let actions=0;actions<150;actions++){
   s=await state();const g=s.hand,t=s.tournament;
   if(g.blind>4){sawIncrease=true;
    const hostedEvent=(await(await fetch(origin+'/api/hosted')).json()).find(e=>e.name==='Club test');
    assert.equal(hostedEvent.currentBlind,g.blind);assert.equal(hostedEvent.level,t.level);
   }
   if(g.end&&s.number!==last){
     const expected=Array(count).fill(0);
     for(let unit=1;unit<=Math.max(...g.committed);){
       const payers=indices.filter(i=>g.committed[i]>=unit);
       const high=Math.min(...payers.map(i=>g.committed[i]));
       const amount=(high-unit+1)*payers.length;unit=high+1;
       if(payers.length===1){expected[payers[0]]+=amount;continue}
       const eligible=payers.filter(i=>!g.folded[i]);
       let wins=eligible;
       if(eligible.length>1){
         const ranked=eligible.map(i=>best([...g.cards[i],...g.board]));
         wins=eligible.filter((_,j)=>ranked.every(r=>compare(ranked[j],r)>=0));
       }
       wins.sort((a,b)=>(a-g.button+count-1)%count-(b-g.button+count-1)%count);
       wins.forEach((i,k)=>expected[i]+=Math.floor(amount/wins.length)+Number(k<amount%wins.length));
     }
     assert.deepEqual(g.end.payouts,expected);
     if(stackBefore.filter(n=>n>0).length===2)sawHeadsUp=true; // Blind all-ins can settle before any manual action.
     assert.deepEqual(g.stacks,expected.map((x,i)=>stackBefore[i]-g.committed[i]+x));
 assert.equal(g.stacks.reduce((a,b)=>a+b,0),count*100);stackBefore=[...g.stacks];last=s.number;
     for(const i of eliminated)assert.equal(g.committed[i],0);
     for(let i=0;i<count;i++)if(!g.stacks[i]){assert.ok(t.out[i]);eliminated.add(i)}
     console.log('Tournament hand',last,'blinds',g.blind/2,g.blind,'stacks',g.stacks);
   }
   if(t.winner!==null)break;
   if(g.end){await until(async()=>(await state()).number>s.number);continue}
   if(eliminated.size===count-2)sawHeadsUp=true;
   assert.ok(!eliminated.has(g.turn));
   const i=g.turn,own=await state(i),o=own.hand.options;
   // Get to heads-up by playing two seats against one another at a time.
   const live=stackBefore.map((v,j)=>v?j:-1).filter(j=>j>=0);
   const battle=last===0?[1,2]:live.slice(0,2);
   const re=!battle.includes(i)&&o.due?/^Fold$/:battle.includes(i)&&o.raise?/^All in$/:o.due?/^Call /:/^Check$/;
   await click(i,re);await until(async()=>(await state()).version>s.version);
 }
 s=await state();const w=s.tournament.winner;
 assert.notEqual(w,null);assert.deepEqual([...s.tournament.finishes].sort((a,b)=>a-b),indices.map(i=>i+1));assert.equal(s.tournament.finishes[w],1);assert.equal(eliminated.size,count-1);assert.ok(sawIncrease);assert.ok(sawHeadsUp);
 const prizes=Array(count).fill(0);prizes[w]=count*25;
 for(let i=0;i<count;i++){
   const final=await state(i);assert.deepEqual(final.tournament.prizes,prizes);assert.equal(final.hand.stacks[w],count*100);
   await until(()=>clients[i].run("document.querySelector('#status')?.textContent.includes('Tournament winner:')"));
 }
 const inspectTournamentHistory=async()=>{
  if(!process.argv.includes('--history-mode'))return;
  const c=clients[w];await c.size(1196,929);await until(()=>c.run("!!document.querySelector('#tableHandHistory:not([disabled])')"));await c.run("document.querySelector('#tableHandHistory').click()");await until(()=>c.run("!!document.querySelector('.historyPreview')"));const notes=(await api(c,'notes'))[1],number=await c.run("Number(document.querySelector('.hudHandDetail').dataset.hand)"),h=notes.self.hands.find(h=>h.number===number);assert.ok(notes.self.hands.every(h=>h.mode==='tournament'));assert.equal(h.names.length,count);
  const pose=await c.run("(async()=>{const p=document.querySelector('.historyPreview'),r=p.getBoundingClientRect(),i=new Image();i.src=getComputedStyle(p).backgroundImage.slice(5,-2);await i.decode();return {src:i.src,size:[i.naturalWidth,i.naturalHeight],seats:[...p.querySelectorAll('.historyPreviewSeat')].map(s=>{const b=s.getBoundingClientRect();return {seat:Number(s.dataset.seat),x:(b.x-r.x)/r.width*640+48,y:(b.y-r.y)/r.width*640+50,cards:s.querySelectorAll('.historyPreviewHole').length}})}})()");assert.ok(pose.src.endsWith('native-history-preview-tournament.png'));assert.deepEqual(pose.size,[640,460]);assert.equal(pose.seats.length,h.initialStacks.filter(n=>n>0).length);const positions=count===3?[[320,395],[65,130],[575,130]]:count===4?[[320,395],[60,225],[320,63],[580,225]]:[[320,395],[65,310],[65,130],[320,65],[575,130],[575,310]];for(const seat of pose.seats){const p=positions[(seat.seat-h.viewerSeat+count)%count];assert.ok(Math.abs(seat.x-p[0])<.1&&Math.abs(seat.y-p[1])<.1);assert.equal(seat.cards,h.cards[seat.seat]?.length||0)}assert.equal(await c.run("document.querySelectorAll('.historyActionColumn').length"),5);await c.run("document.querySelector('.historyHide').click()");assert.equal(await c.run("document.querySelector('.historyReportTitle').textContent"),'');await c.run("document.querySelector('.historyHide').click();document.querySelector('.historyUnits').click()");assert.equal(await c.run("document.querySelector('.historyPreviewPot [data-history-chips]').textContent.endsWith(' BB')"),true);await c.run("document.querySelector('.historyUnits').click();document.querySelector('.historyClose').click()");assert.deepEqual((await state()).tournament.prizes,prizes);
  console.log('PASS '+count+'seat default tournament history:original640x460background,active seats/private cards,5columns/Hide/BB andunchanged prize');
 };
 await inspectTournamentHistory();
 assert.equal((await api(clients[w],'ready',{version:s.version}))[0],409);
 await stop(server);await boot();await clients[w].go(url);
 assert.deepEqual((await until(async()=>{try{return (await state(w)).tournament}catch{return false}})).prizes,prizes);
 await inspectTournamentHistory();
 console.log('PASS '+count+' registered browsers; scheduled levels, '+(count-1)+' eliminations, heads-up, persisted final prize. Winner: Player',w+1,'prizes:',prizes);
}

function verifyHandPayout(g,count,variant='plo'){
 const expected=Array(count).fill(0),indices=Array.from({length:count},(_,i)=>i);
 for(let unit=1;unit<=Math.max(...g.committed);){
  const payers=indices.filter(i=>g.committed[i]>=unit),high=Math.min(...payers.map(i=>g.committed[i])),amount=(high-unit+1)*payers.length;unit=high+1;
  if(payers.length===1){expected[payers[0]]+=amount;continue}
  const eligible=payers.filter(i=>!g.folded[i]);let winners=eligible;
  if(eligible.length>1){
   const ranks=eligible.map(i=>{if(variant==='shortdeck')return bestShortDeck([...g.cards[i],...g.board]);if(variant==='holdem')return best([...g.cards[i],...g.board]);let top=null;const h=g.cards[i];
    for(let a=0;a<h.length-1;a++)for(let b=a+1;b<h.length;b++)for(let x=0;x<g.board.length-2;x++)for(let y=x+1;y<g.board.length-1;y++)for(let z=y+1;z<g.board.length;z++){
     const rank=best([h[a],h[b],g.board[x],g.board[y],g.board[z]]);if(!top||compare(rank,top)>0)top=rank;
    }return top;
   });winners=eligible.filter((_,j)=>ranks.every(r=>compare(ranks[j],r)>=0));
  }
  winners.sort((a,b)=>(a-g.button+count-1)%count-(b-g.button+count-1)%count);
  winners.forEach((i,k)=>expected[i]+=Math.floor(amount/winners.length)+Number(k<amount%winners.length));
 }
 assert.deepEqual(g.end.payouts,expected);
}
